<?php require_once 'config.php';require_once 'lang.php';$langue=$_COOKIE['langue']??'fr';$titre_page=t('titre_rapports');$total=$connexion->query('SELECT COUNT(*) n FROM employes')->fetch_assoc()['n'];$r=$connexion->query('SELECT poste,COUNT(*) nombre FROM employes GROUP BY poste ORDER BY nombre DESC');include 'inclure_entete.php';?><header><h1><?=t('titre_rapports')?></h1></header><section class="stats"><div><?=$total?><br><?=t('effectif_total')?></div></section><section class="carte"><h2><?=t('repartition_postes')?></h2><table><?php while($x=$r->fetch_assoc()):?><tr><td><?=htmlspecialchars($x['poste'])?></td><td><?=$x['nombre']?> <?=t('employe_s')?></td></tr><?php endwhile;?></table></section><?php include 'inclure_pied.php';?>
